2	import { createParamDecorator } from './create-route-param-metadata.decorator.js';
3	
4	/**
5	 * Symbol used to carry the per-request SSE `AbortController` on the request object.
6	 *
7	 * The controller is attached by the framework before the route handler runs and is
8	 * aborted when the client disconnects. Its signal is exposed to route handlers
9	 * through the `@SseSignal()` parameter decorator.
10	 *
11	 * @publicApi
12	 */
13	export const SSE_ABORT_CONTROLLER = Symbol('SSE_ABORT_CONTROLLER');
14	
15	/**
16	 * Route handler parameter decorator that injects the `AbortSignal` associated
17	 * with a Server-Sent-Events (SSE) request.
18	 *
19	 * The signal represents the lifetime of the SSE response: it is aborted once the
20	 * stream terminates, whether because the client disconnected, the `Observable`
21	 * completed, or it errored. Tying setup-phase resources to the signal therefore
22	 * releases them exactly once on every exit path, including resources allocated
23	 * before the returned `Observable` exists — which would otherwise leak, since the
24	 * producer is never subscribed once the client has disconnected.
25	 *
26	 * Because the signal also aborts on normal completion, `signal.aborted` is only
27	 * meaningful as a "did the client go away?" check *during setup*, before the
28	 * `Observable` is returned; at that point the stream cannot have completed yet.
29	 * Cleanup wired to the `abort` event should be idempotent, as it may run
30	 * alongside the `Observable`'s own teardown.
31	 *
32	 * @example
33	 * ```ts
34	 * @Sse('stream')
35	 * async stream(@SseSignal() signal: AbortSignal): Promise<Observable<MessageEvent>> {
36	 *   const session = await createSession();
37	 *   if (signal.aborted) {
38	 *     await session.close();
39	 *     return EMPTY;
40	 *   }
41	 *   return new Observable(subscriber => {
42	 *     const stream = startGeneration(session);
43	 *     signal.addEventListener('abort', () => stream.stop(), { once: true });
44	 *     return () => stream.stop();
45	 *   });
46	 * }
47	 * ```
48	 *
49	 * @publicApi
50	 */
51	export const SseSignal: () => ParameterDecorator = createParamDecorator(
52	  (_data: unknown, ctx: ExecutionContext): AbortSignal | undefined => {
53	    const request = ctx.switchToHttp().getRequest();
54	    const controller: AbortController | undefined =
55	      request?.[SSE_ABORT_CONTROLLER];
56	    return controller?.signal;
57	  },
58	);
